/* Reset & Global pixel variables */
:root {
  --color-bg: #22252c;
  --color-card: #f4edd4;
  --color-panel: #e3d9b8;
  --color-dark: #1b1c1e;
  --color-accent: #2e6047;
  --color-accent-hover: #3d795a;
  --color-danger: #bd2b2b;
  --color-danger-hover: #d93d3d;
  --color-over: #e61c24;
  --color-border: #1b1c1e;
  --shadow-pixel: 4px 4px 0px var(--color-border);
  --shadow-pixel-pressed: 1px 1px 0px var(--color-border);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* Ensure hidden attribute overrides any display rules */
[hidden] {
  display: none !important;
}

body {
  background-color: var(--color-bg);
  /* Pixel grid pattern background */
  background-image: 
    linear-gradient(45deg, #1e2026 25%, transparent 25%), 
    linear-gradient(-45deg, #1e2026 25%, transparent 25%), 
    linear-gradient(45deg, transparent 75%, #1e2026 75%), 
    linear-gradient(-45deg, transparent 75%, #1e2026 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0px;
  font-family: "Courier New", Courier, monospace, system-ui;
  font-size: 16px;
  color: var(--color-dark);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 20px 12px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* Card container */
.pixel-card {
  background: var(--color-card);
  border: 4px solid var(--color-border);
  box-shadow: 8px 8px 0px rgba(0, 0, 0, 0.6);
  width: 100%;
  max-width: 480px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.card-header {
  text-align: center;
  border-bottom: 4px dashed var(--color-border);
  padding-bottom: 12px;
}

.title {
  font-size: 1.6rem;
  letter-spacing: -0.5px;
  text-transform: uppercase;
  color: var(--color-dark);
}

.subtitle {
  font-size: 1rem;
  color: #555;
  margin-top: 4px;
}

/* Section container boxes */
.section-box {
  background: var(--color-panel);
  border: 3px solid var(--color-border);
  padding: 12px;
  box-shadow: var(--shadow-pixel);
}

.section-title {
  font-size: 1.1rem;
  margin-bottom: 10px;
  text-transform: uppercase;
  border-bottom: 2px solid var(--color-border);
  padding-bottom: 4px;
}

/* Form elements */
.form-row {
  display: flex;
  gap: 8px;
  align-items: flex-end;
}

.flex-grow {
  flex: 1;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 10px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 8px;
}

label {
  font-size: 0.95rem;
  font-weight: bold;
  color: var(--color-dark);
}

input[type="text"],
input[type="number"] {
  background: #ffffff;
  border: 3px solid var(--color-border);
  font-family: inherit;
  font-size: 1rem;
  padding: 8px;
  color: var(--color-dark);
  box-shadow: inset 2px 2px 0px rgba(0, 0, 0, 0.2);
  outline: none;
  width: 100%;
}

input:focus {
  outline: 3px solid var(--color-accent);
  background-color: #fffde7;
}

/* Pixel Buttons */
.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 8px 12px;
  color: #ffffff;
  background: var(--color-accent);
  border: 3px solid var(--color-border);
  box-shadow: var(--shadow-pixel);
  cursor: pointer;
  text-transform: uppercase;
  transition: none;
}

.pixel-btn:hover {
  background: var(--color-accent-hover);
}

.pixel-btn:active {
  transform: translate(3px, 3px);
  box-shadow: var(--shadow-pixel-pressed);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--color-dark);
}

.btn-secondary {
  background: #47525d;
}
.btn-secondary:hover {
  background: #5d6a78;
}

.btn-danger {
  background: var(--color-danger);
  padding: 4px 8px;
  font-size: 0.9rem;
}
.btn-danger:hover {
  background: var(--color-danger-hover);
}

.full-width {
  width: 100%;
  margin-top: 4px;
}

/* Item List */
.grocery-items {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 240px;
  overflow-y: auto;
  padding: 2px;
}

.grocery-item {
  background: #ffffff;
  border: 2px solid var(--color-border);
  box-shadow: 2px 2px 0px var(--color-border);
  padding: 8px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.item-info {
  display: flex;
  flex-direction: column;
  word-break: break-word;
}

.item-name-text {
  font-weight: bold;
  font-size: 1rem;
}

.item-meta-text {
  font-size: 0.85rem;
  color: #555;
}

.item-action {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.item-total-price {
  font-weight: bold;
  font-size: 1rem;
}

.empty-state {
  text-align: center;
  font-style: italic;
  color: #666;
  padding: 12px 0;
}

/* Summary & Budget highlights */
.summary-panel {
  background: var(--color-panel);
  border: 4px solid var(--color-border);
  box-shadow: var(--shadow-pixel);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.summary-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 1.05rem;
  font-weight: bold;
}

.summary-row.total-highlight {
  border-top: 2px dashed var(--color-border);
  padding-top: 6px;
}

.budget-alert {
  background: #ffdede;
  border: 2px solid var(--color-over);
  color: var(--color-over);
  font-weight: bold;
  text-align: center;
  padding: 6px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* Red highlight when over budget */
.over-budget {
  color: var(--color-over) !important;
  background-color: #ffd8d8;
  padding: 0 4px;
  border: 2px solid var(--color-over);
}

/* Responsive adjustments */
@media (max-width: 380px) {
  body {
    padding: 8px;
  }
  .pixel-card {
    padding: 12px;
  }
  .form-row {
    flex-direction: column;
    align-items: stretch;
  }
  .form-grid {
    grid-template-columns: 1fr;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Application State
  let budget = 50.0;
  let items = [];

  // DOM Element References
  const budgetForm = document.getElementById('budget-form');
  const budgetInput = document.getElementById('budget-input');
  const budgetDisplay = document.getElementById('budget-display');

  const itemForm = document.getElementById('item-form');
  const itemNameInput = document.getElementById('item-name');
  const itemPriceInput = document.getElementById('item-price');
  const itemQtyInput = document.getElementById('item-qty');

  const groceryList = document.getElementById('grocery-list');
  const emptyNotice = document.getElementById('empty-notice');
  const totalDisplay = document.getElementById('total-display');
  const leftDisplay = document.getElementById('left-display');
  const budgetAlert = document.getElementById('budget-alert');

  // Helper formatting
  function formatCurrency(amount) {
    return '$' + amount.toFixed(2);
  }

  // Core Calculation and Render
  function render() {
    // Calculate running total
    const runningTotal = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const remainingBudget = budget - runningTotal;
    const isOverBudget = runningTotal > budget;

    // Update list view
    groceryList.innerHTML = '';
    if (items.length === 0) {
      emptyNotice.removeAttribute('hidden');
    } else {
      emptyNotice.setAttribute('hidden', '');
      items.forEach((item) => {
        const li = document.createElement('li');
        li.className = 'grocery-item';

        const infoDiv = document.createElement('div');
        infoDiv.className = 'item-info';

        const nameSpan = document.createElement('span');
        nameSpan.className = 'item-name-text';
        nameSpan.textContent = item.name;

        const metaSpan = document.createElement('span');
        metaSpan.className = 'item-meta-text';
        metaSpan.textContent = `${item.quantity} × ${formatCurrency(item.price)}`;

        infoDiv.appendChild(nameSpan);
        infoDiv.appendChild(metaSpan);

        const actionDiv = document.createElement('div');
        actionDiv.className = 'item-action';

        const totalSpan = document.createElement('span');
        totalSpan.className = 'item-total-price';
        totalSpan.textContent = formatCurrency(item.price * item.quantity);

        const deleteBtn = document.createElement('button');
        deleteBtn.type = 'button';
        deleteBtn.className = 'pixel-btn btn-danger';
        deleteBtn.textContent = '✖';
        deleteBtn.setAttribute('aria-label', `Remove ${item.name}`);
        deleteBtn.dataset.id = item.id;

        actionDiv.appendChild(totalSpan);
        actionDiv.appendChild(deleteBtn);

        li.appendChild(infoDiv);
        li.appendChild(actionDiv);
        groceryList.appendChild(li);
      });
    }

    // Update summary values
    budgetDisplay.textContent = formatCurrency(budget);
    totalDisplay.textContent = formatCurrency(runningTotal);
    leftDisplay.textContent = formatCurrency(remainingBudget);

    // Highlight running total and show alert if over budget
    if (isOverBudget) {
      totalDisplay.classList.add('over-budget');
      leftDisplay.classList.add('over-budget');
      budgetAlert.removeAttribute('hidden');
    } else {
      totalDisplay.classList.remove('over-budget');
      leftDisplay.classList.remove('over-budget');
      budgetAlert.setAttribute('hidden', '');
    }
  }

  // Event Handlers using addEventListener
  budgetForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const newBudget = parseFloat(budgetInput.value);
    if (!isNaN(newBudget) && newBudget >= 0) {
      budget = newBudget;
      render();
    }
  });

  itemForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = itemNameInput.value.trim();
    const price = parseFloat(itemPriceInput.value);
    const quantity = parseInt(itemQtyInput.value, 10);

    if (name && !isNaN(price) && price > 0 && !isNaN(quantity) && quantity > 0) {
      items.push({
        id: Date.now().toString() + Math.random().toString(36).substr(2, 5),
        name,
        price,
        quantity
      });

      // Reset item inputs
      itemNameInput.value = '';
      itemPriceInput.value = '';
      itemQtyInput.value = '1';
      itemNameInput.focus();

      render();
    }
  });

  groceryList.addEventListener('click', (e) => {
    const target = e.target.closest('button.btn-danger');
    if (!target) return;

    const itemId = target.dataset.id;
    if (itemId) {
      items = items.filter((item) => item.id !== itemId);
      render();
    }
  });

  // Initial render
  render();
});
